INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'The maximum number of individuals an ecosystem can support long-term without exhausting its resources is called:', 'Population density', 'Carrying capacity', 'Birth rate', 'Death rate', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'Any factor that prevents a population from growing larger is called a:', 'Limiting factor', 'Density factor', 'Growth factor', 'Carrying factor', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'Which is NOT a common limiting factor for most animal populations?', 'Clean water', 'Shelter or space', 'Body color of individuals', 'Adequate food', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'When a population grows rapidly with no limiting factors, it forms a:', 'Flat line', 'S-shaped curve', 'Wavy line', 'J-shaped curve (exponential growth)', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'As a population approaches its carrying capacity, its growth rate:', 'Slows down and approaches zero', 'Speeds up', 'Becomes infinite', 'Stays exactly the same', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'The S-shaped population growth pattern is called:', 'Boom-and-bust growth', 'Exponential growth', 'Logistic growth', 'Negative growth', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'A lack of available mates in a small population will:', 'Cause exponential growth', 'Limit population growth', 'Increase carrying capacity', 'Have no effect', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'In a logistic growth curve, the flat portion at the top represents:', 'Rapid growth', 'Population crash', 'Exponential phase', 'Carrying capacity (stable population size)', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'A drought causes most plants in a grassland to die, leading to a decline in rabbit numbers. The drought is a:', 'Limiting factor', 'Growth factor', 'Carrying capacity increase', 'Mate factor', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'Population density refers to:', 'Birth rate minus death rate', 'Carrying capacity', 'Number of individuals per unit area or volume', 'Total number of individuals only', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'A forest originally supports 500 deer. After a typhoon destroys much of the habitat, the carrying capacity will most likely:', 'Double to 1000', 'Stay the same', 'Decrease', 'Become unlimited', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'Which is an example of a density-dependent limiting factor?', 'Disease or food shortage', 'Typhoon', 'Earthquake', 'Volcanic eruption', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'Which is a density-independent limiting factor?', 'Predation', 'Competition for mates', 'Parasitism', 'Super typhoon', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'Why does population growth slow as it nears carrying capacity?', 'Carrying capacity keeps increasing', 'Limiting factors disappear', 'All organisms stop reproducing', 'Competition for resources becomes stronger', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'pre_test', 'Rats increase in a rice field, followed by an increase in snakes that feed on them. Snake predation is a:', 'Biotic limiting factor', 'Carrying capacity increaser', 'Abiotic factor', 'Growth promoter', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'In nature, what usually happens after exponential growth?', 'It continues forever', 'Limiting factors slow growth or cause a population crash', 'Carrying capacity disappears', 'Resources become unlimited', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'If a population is below carrying capacity, it will usually:', 'Go extinct', 'Stay exactly the same', 'Increase toward carrying capacity', 'Decrease rapidly', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'A landfill destroys most of a frog''s breeding pond. Which limiting factor is affected the most?', 'Water', 'Food', 'Mates', 'Shelter or breeding space', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'Which pair consists of abiotic limiting factors?', 'Water availability and temperature extremes', 'Predators and parasites', 'Competition and disease', 'Food supply and mates', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'The current growth of the human population most closely follows which pattern?', 'Stable S-curve', 'Rising J-curve or early logistic growth', 'Rapid decline', 'Zero growth', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'What is the correct sequence of logistic growth?', 'Stable → Fast → Slow', 'Crash → Fast → Stable', 'Slow → Fast → Slowing → Stable at carrying capacity', 'Stable → Crash → Fast', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'If a population exceeds its carrying capacity, what is most likely to happen?', 'Growth continues rapidly', 'Carrying capacity permanently increases', 'A population crash occurs because of resource shortages', 'Nothing changes', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'A lake can support 1,000 tilapia, but 1,200 are introduced. What will most likely happen?', 'The carrying capacity becomes 1,200', 'All survive', 'Exponential growth continues', 'Many die until the population returns near carrying capacity', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'Why are mates considered a limiting factor in small isolated populations?', 'Individuals have difficulty finding mates, reducing reproduction', 'Mates increase carrying capacity', 'Food competition increases', 'Males always fight', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'What is the main difference between density-dependent and density-independent limiting factors?', 'Independent factors are always living things', 'Density-dependent effects become stronger as population density increases', 'Density-dependent factors never cause extinction', 'They have exactly the same effects', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'Which situation best illustrates a population slowing as it approaches carrying capacity?', 'A volcano kills most birds', 'A new species grows without limits', 'Mouse population: 100 → 180 → 210 → 215 → 212', 'Disease wipes out rabbits', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'How does competition affect populations near carrying capacity?', 'It increases resources', 'It removes predators', 'It automatically raises carrying capacity', 'Fewer individuals survive and reproduce because resources are limited', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'Protecting both food sources and nesting sites for the Philippine Eagle helps because:', 'Carrying capacity depends on all essential resources', 'Eagles do not need mates', 'Only food matters', 'Carrying capacity never changes', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000201', 1, 'post_test', 'Why can''t exponential population growth continue forever?', 'Death rates always decrease', 'Resources are limited in every ecosystem', 'Carrying capacity increases endlessly', 'Birth rates suddenly stop', 'B', 'Option B is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Biotechnology is best defined as:', 'Only genetic engineering', 'Growing plants only', 'Using living organisms or biological processes to make useful products', 'Only laboratory work', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Traditional food biotechnology mainly depends on:', 'Fermentation by microorganisms', 'Freezing', 'Canning', 'Boiling', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Nata de coco is produced by fermenting coconut water with:', 'Mold', 'Yeast', 'Acetobacter xylinum', 'Lactic acid bacteria', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Vinegar is produced when alcohol is converted into:', 'Citric acid', 'Acetic acid', 'Hydrochloric acid', 'Lactic acid', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Cheese, yogurt, and pickles are made using bacteria that produce:', 'Lactic acid', 'Oxygen', 'Alcohol', 'Acetic acid', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Soy sauce is traditionally made from:', 'Coconut milk', 'Rice only', 'Fruit juice', 'Soybeans, grains, mold, and bacteria', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'GMOs are organisms whose ____ has been altered in a laboratory.', 'Cell size', 'DNA or genetic material', 'Food value only', 'Color only', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'In Vitro Fertilization (IVF) takes place:', 'Outside the body before implantation', 'Without sperm and egg', 'Inside the body', 'With one parent only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'One benefit of pest-resistant GMO crops is:', 'They never spoil', 'Need more water', 'Less pesticide use and higher yield', 'Better taste', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Which is an ethical concern related to IVF?', 'It always causes disease', 'It always succeeds', 'It produces only identical twins', 'Issues involving embryos, cost, and fairness', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Which list contains only traditional fermented foods?', 'Cheese, soy sauce, vinegar, nata de coco, and yogurt', 'Bt corn', 'Modern medicines', 'Insulin and vaccines', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Baker''s yeast helps bread rise by producing:', 'Oxygen', 'Acetic acid', 'Carbon dioxide and alcohol', 'Lactic acid', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'Golden Rice was developed to provide more:', 'Iron', 'Beta-carotene (Vitamin A precursor)', 'Protein', 'Vitamin C', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'One environmental concern about Bt corn is:', 'Pests may become resistant and non-target insects may be affected', 'It stops photosynthesis', 'It requires much more water', 'It kills all nearby plants', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'pre_test', 'One concern about GMOs for Filipino farmers is:', 'They are always poisonous', 'They grow only in cold climates', 'Patented seeds may increase farming costs', 'They always taste worse', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Most modern insulin is produced by:', 'Blood donations', 'Bacteria carrying the human insulin gene', 'Chemical synthesis only', 'Pig pancreas only', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Which pairing is correct?', 'Vinegar – Acetic acid bacteria', 'Bread – Mold', 'Yogurt – Yeast only', 'Nata de coco – Lactobacillus', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Fermentation is considered ancient biotechnology because:', 'It requires modern laboratories', 'It uses DNA editing', 'It is only for modern foods', 'It was practiced long before microbes were understood', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Cloning produces offspring that are:', 'Genetically identical to one parent', 'Always stronger', 'Unable to reproduce', 'Genetically unique', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'A major ethical issue in gene editing with CRISPR is:', 'It only works on plants', 'Unintended effects and designer baby concerns', 'It cures nothing', 'It is completely safe', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'What is the correct sequence in traditional vinegar production?', 'Alcohol → Sugar', 'Lactic acid → Alcohol', 'Sugar → Yeast → Alcohol → Bacteria → Acetic acid', 'Sugar → Acid directly', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Nata de coco is formed from:', 'Milk protein', 'Yeast foam', 'Bacterial cellulose', 'Boiled coconut water', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'The Cartagena Protocol focuses on:', 'Cheese making', 'Human cloning', 'IVF regulations', 'Safe handling and trade of genetically modified organisms', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'An environmental benefit of approved GMO crops is:', 'Reduced use of chemical pesticides and fertilizer runoff', 'They replace all wild plants', 'They grow only in one season', 'They require more fertilizer', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'One economic concern about IVF is:', 'It always causes infertility', 'High cost limits access for many families', 'It always produces boys', 'It is always dangerous', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Fermentation helps preserve food because it:', 'Dries food completely', 'Uses only salt', 'Produces acids or alcohol that slow spoilage microorganisms', 'Heats food', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Bt corn contains a gene that:', 'Makes the plant glow', 'Eliminates the need for water', 'Makes corn sweeter', 'Produces a protein harmful to certain insect pests', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Traditional and modern biotechnology differ because:', 'Traditional uses selection and fermentation, while modern changes DNA directly', 'Traditional never uses microbes', 'Modern is always safer', 'Only modern biotechnology produces food', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'One ethical trade-off in IVF is:', 'Success is guaranteed', 'There is no cost involved', 'Extra embryos may be frozen or discarded', 'There are no risks', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000202', 1, 'post_test', 'Compared with traditional breeding, modern biotechnology:', 'Is only used in rich countries', 'Changes specific genes directly', 'Cannot improve crop yield', 'Uses no science', 'B', 'Option B is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', 'Theory that Earth''s outer shell moves in slabs:', 'Earthquake theory', 'Plate Tectonics', 'Continental drift', 'Seafloor spreading', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ B — Plate tectonics unifies how plates move and interact. 2. The rigid moving slabs are called:', 'Fault blocks', 'Asthenosphere', 'Mantle plumes', 'Tectonic / lithospheric plates', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ D — The lithosphere is broken into moving plates. 3. Plates move at about the speed of:', 'A runner', 'Fingernails growing', 'A car', 'A jet', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ B — Typical speed is a few centimeters per year. 4. Modern tool to measure plate motion precisely:', 'Thermometer', 'GPS satellites', 'Compass', 'Barometer', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ B — GPS tracks position to millimeters over time. 5. Plates moving apart:', 'Subduction', 'Transform', 'Divergent', 'Convergent', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ C — Divergent boundaries create new crust. 6. Plates colliding:', 'Divergent', 'Ridge', 'Transform', 'Convergent', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ D — Convergent boundaries destroy or thicken crust. 7. Plates sliding past each other:', 'Trench', 'Convergent', 'Transform fault', 'Divergent', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ C — Transform boundaries have no creation or destruction of crust. 8. Soft flowing layer under plates:', 'Crust', 'Core', 'Asthenosphere', 'Lithosphere', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ C — The asthenosphere allows plates to move. 9. One plate sinking under another:', 'Spreading', 'Faulting', 'Subduction', 'Rifting', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ C — Dense oceanic plate sinks into the mantle. 10. Main fault system in the Philippines:', 'East African Rift', 'San Andreas', 'Philippine Fault System', 'Marikina Fault only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ C — It runs the length of the archipelago. 11. Continent-continent collision forms:', 'Tall non-volcanic mountains', 'Island arcs', 'Trenches', 'Volcanoes', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ A — No subduction means no melting for magma. 12. Ocean-continent collision produces:', 'Mid-ocean ridge', 'Trench + continental volcanic arc', 'Rift valley', 'Transform fault', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ B — Subduction melts rock to feed volcanoes on land. 13. The Philippines sits between:', 'Nazca and South American Plates', 'Indian and African Plates', 'Philippine Sea Plate and Eurasian Plate', 'Pacific and North American Plates', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ C — Interaction of these plates forms our geology. 14. Many Philippine volcanoes and trenches exist because:', 'No plate motion', 'Several plates are subducting around us', 'We are on a hot spot only', 'Plates are moving apart', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'pre_test', '✅ B — Multiple subduction zones ring the country. 15. Transform boundaries commonly have:', 'Strong shallow earthquakes', 'Trenches', 'Volcanoes', 'New crust', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ A — Friction builds then slips in quakes; no melting. 16. Himalayas formed when:', 'Indian Plate collided with Eurasian Plate', 'Plates moved apart', 'Ocean plate melted', 'Plates slid sideways', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ A — Two continents crumpled together. 17. Andes Mountains formed from:', 'Rifting', 'Continent-continent push', 'Hot spot', 'Nazca Plate subducting under South America', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ D — Ocean plate diving under the continent. 18. Main driver of plate motion:', 'Wind', 'Earth''s spin', 'Mantle convection currents', 'Moon pull', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ C — Heat rising and sinking moves the plates. 19. Subduction leads to:', 'No change', 'Melting, magma, volcanoes, folded mountains', 'Only erosion', 'Rifting', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ B — Sinking rock heats, melts, and rises. 20. New seafloor is created at:', 'Faults', 'Volcanoes', 'Trenches', 'Mid-ocean ridges / divergent boundaries', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ D — Magma rises, cools, and adds new crust. 21. Plate moving 7 cm/year for 50 million years travels:', '700 km', '350 km', '3500 km', '7000 km', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ C — 7 cm × 50,000,000 = 3,500 km. 22. Why is GPS better than older methods?', 'Precise, continuous, global', 'Works only on land', 'Needs no power', 'Cheaper only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ A — It gives accurate real-time motion data. 23. Mariana and Philippine Trenches are:', 'Hot spots', 'Rift valleys', 'Transform features', 'Subduction trenches', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ D — They mark where plates sink. 24. Correct match for the Philippines:', 'Divergent → Mayon', 'Transform → Taal', 'Convergent → Mayon Volcano + Manila Trench', 'Hot spot → Manila Trench', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ C — Both come from subduction at convergent boundaries. 25. No volcanoes at the Himalayas because:', 'No dense ocean plate to sink and melt', 'No earthquakes', 'Too dry', 'Too cold', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ A — Continental rock is too light to subduct. 26. Asthenosphere is:', 'Rigid metal', 'Cold brittle rock', 'Hot solid rock that flows slowly', 'Liquid rock', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ C — It is solid but ductile over millions of years. 27. Trenches on both sides of the Philippines mean:', 'No plate motion', 'Plates are pulling apart', 'We are squeezed between subduction zones', 'Only earthquakes', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ C — The archipelago sits in a collision zone. 28. Philippine Fault System is a:', 'Divergent rift', 'Left-lateral transform fault', 'Hot spot', 'Subduction zone', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ B — Blocks slide past each other horizontally. 29. Ocean-ocean subduction makes ______; ocean-continent makes ______:', 'Mountains / plains', 'No trench / no trench', 'Volcanic island arc / continental volcanic arc', 'Rift / ridge', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000203', 1, 'post_test', '✅ C — One makes islands, the other land mountains. 30. Origin of the Philippines:', 'Ocean floor uplifted all at once', 'Meteor impact', 'Merged small volcanic island arcs', 'One continent split', 'A', 'Option A is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', 'Climate is the long-term average of:', 'Weather', 'Climate', 'Season', 'Forecast', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ A — Climate describes average weather conditions over many years. 2. Which term refers to the increase in Earth''s average temperature?', 'Ice age', 'Coriolis effect', 'Global warming', 'Cooling', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ C — It is the long-term rise in global air and ocean temperatures. 3. Climate change includes:', 'Only hotter summers', 'Changes in rainfall, sea level, and temperature', 'Daily weather changes only', 'Air pollution only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ B — Climate change involves many long-term environmental changes. 4. Gases that trap heat in Earth''s atmosphere are called:', 'Noble gases', 'Nitrogen gases', 'Ozone gases', 'Greenhouse gases', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ D — These gases help keep heat near Earth''s surface. 5. The main greenhouse gas released by human activities is:', 'Nitrogen', 'Argon', 'Carbon dioxide (CO₂)', 'Ozone', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ C — Burning fossil fuels releases large amounts of CO₂. 6. The natural greenhouse effect is important because it:', 'Makes Earth too hot', 'Keeps Earth warm enough for life', 'Causes storms', 'Freezes the planet', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ B — Without it, Earth would be too cold to support life. 7. The enhanced greenhouse effect happens when:', 'Less heat is trapped', 'Extra greenhouse gases trap more heat', 'Heat escapes faster', 'Earth''s atmosphere disappears', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ B — Human activities strengthen the natural greenhouse effect. 8. Melting glaciers and ice sheets directly cause:', 'Lower sea level', 'Less rainfall', 'Sea level rise', 'Cooler oceans', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ C — Melted land ice adds more water to the oceans. 9. Ice core records show that modern CO₂ levels are:', 'Lower than before', 'About the same as always', 'Slightly lower than natural levels', 'Higher than at any time in the last 800,000 years', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ D — Today''s CO₂ levels are far above natural historical levels. 10. Besides melting ice, sea level rises because:', 'Oceans become saltier', 'Warm water expands', 'More rain falls into the ocean', 'Winds push water upward', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ B — Heated water occupies more space. 11. Which group contains major greenhouse gases?', 'Oxygen, nitrogen, helium', 'CO₂, methane, nitrous oxide, CFCs, water vapor', 'Hydrogen, helium, argon', 'Dust and smoke', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ B — These gases absorb and re-emit heat. 12. Which human activities produce large amounts of methane?', 'Volcanoes only', 'Cars only', 'Cattle, rice fields, landfills, and gas leaks', 'Oceans only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ C — Agriculture and waste are major methane sources. 13. CFCs are harmful because they:', 'Cool the atmosphere', 'Trap heat and damage the ozone layer', 'Occur naturally in large amounts', 'Remove greenhouse gases', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ B — They are powerful greenhouse gases and ozone-depleting chemicals. 14. Which is strong evidence of climate change?', 'One unusually hot day', 'Rising global temperatures and shrinking glaciers', 'A rainy afternoon', 'One powerful typhoon', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'pre_test', '✅ B — Multiple long-term observations confirm climate change. 15. Deforestation increases global warming because:', 'Trees release more oxygen', 'Forests release stored carbon and absorb less CO₂', 'It creates more rainfall', 'It lowers Earth''s temperature', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Trees store carbon and remove CO₂ from the atmosphere. 16. Which is NOT considered evidence of climate change?', 'One hot day', 'Retreating glaciers', 'Rising sea level', 'Earlier flowering of plants', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ A — Single weather events do not represent climate. 17. Which sequence correctly explains human-caused global warming?', 'More trees → More warming', 'Burning fossil fuels → More CO₂ → Stronger greenhouse effect → Warming', 'Less sunlight → Warming', 'More clouds → Cooling', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Human emissions increase greenhouse gases, causing warming. 18. Why will Earth continue warming even if emissions stop immediately?', 'Volcanoes become stronger', 'CO₂ remains in the atmosphere for centuries and oceans store heat', 'The Sun keeps getting hotter', 'Winds trap heat permanently', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Past emissions continue affecting the climate. 19. The largest human source of CO₂ emissions is:', 'Volcanoes', 'Burning coal, oil, and natural gas', 'Oceans', 'Animals', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Fossil fuel combustion is the biggest contributor. 20. Scientists know extra atmospheric CO₂ comes mainly from fossil fuels because:', 'Carbon isotope evidence matches fossil fuels', 'Volcanoes release the same amount', 'The atmosphere is heavier', 'Ocean temperatures prove it', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ A — Carbon isotope signatures identify fossil fuel emissions. 21. The difference between the natural and enhanced greenhouse effect is that:', 'Both are caused by humans', 'Natural warming supports life, while enhanced warming is caused by extra greenhouse gases', 'Natural warming is harmful', 'Enhanced warming cools Earth', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Human activities increase the natural greenhouse effect. 22. Arctic ice-albedo feedback means:', 'More ice absorbs more heat', 'Less ice exposes darker water, causing more warming and melting', 'Ice cools the atmosphere permanently', 'There is no effect on temperature', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — This positive feedback speeds up Arctic warming. 23. Even a 1°C increase in global temperature is important because it:', 'Causes almost no changes', 'Increases heatwaves, floods, and stronger storms', 'Only affects polar regions', 'Makes oceans colder', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Small global averages can produce major regional impacts. 24. Which chain best explains stronger typhoons in the Philippines?', 'More CO₂ → Less rainfall', 'More greenhouse gases → Warmer oceans → Stronger and wetter typhoons', 'Hotter weather → Fewer storms', 'Cooler oceans → Stronger storms', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Warm ocean water provides more energy for tropical cyclones. 25. Why is the Arctic warming faster than most other places?', 'It receives more sunlight', 'Ice-albedo feedback accelerates warming', 'Stronger winds increase temperature', 'More people live there', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Melting ice exposes darker surfaces that absorb more heat. 26. Why is the statement "Climate changed naturally before, so today''s change is natural" incorrect?', 'Climate has never changed naturally', 'Natural factors cannot explain today''s rapid warming; human emissions do', 'Earth is always warming', 'Ice ages never happened', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — The speed and cause of current warming match human activities. 27. Ocean acidification happens because:', 'Overfishing lowers pH', 'CO₂ dissolves in seawater, forming carbonic acid', 'Warm water becomes acidic by itself', 'Pollution alone causes acidity', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — Carbonic acid lowers ocean pH and harms marine life. 28. Which is a major climate impact already observed in the Philippines?', 'Colder temperatures every year', 'Rising sea levels, stronger typhoons, longer dry seasons, and heavier rains', 'Less rainfall everywhere', 'No noticeable changes', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — These are documented climate-related impacts. 29. Why isn''t water vapor considered the main cause of modern climate change?', 'It does not trap heat', 'It increases after warming begins, acting as a feedback rather than the original cause', 'It is disappearing from the atmosphere', 'It only exists inside clouds', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000204', 1, 'post_test', '✅ B — CO₂ triggers warming; water vapor amplifies it. 30. Ice core records show that atmospheric CO₂ and global temperature:', 'Have no relationship', 'Closely rise and fall together, with today''s CO₂ much higher than past levels', 'Always move in opposite directions', 'Change randomly', 'A', 'Option A is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'ENSO stands for:', 'Weather System', 'El Niño Southern Oscillation', 'Ocean Current', 'Wind Pattern', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'El Niño refers to:', 'Unusually warm eastern and central Pacific Ocean', 'No wind', 'Cool Pacific waters', 'Rain everywhere', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'La Niña is characterized by:', 'No change', 'Global drought', 'Unusually cool eastern Pacific Ocean', 'Warm Pacific waters', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'ENSO develops mainly in the:', 'Atlantic Ocean', 'Indian Ocean', 'Arctic Ocean', 'Tropical Pacific Ocean', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'The normal winds that blow from east to west across the Pacific are called:', 'Trade winds', 'Monsoons', 'Westerlies', 'Jet streams', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'El Niño usually brings which condition to the Philippines?', 'More typhoons', 'Hotter weather and less rainfall', 'Cooler temperatures', 'Flooding', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'La Niña commonly causes:', 'No storms', 'Drought', 'Above-normal rainfall and flooding', 'Hotter weather', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'The "Southern Oscillation" refers to the:', 'Ocean temperature', 'Sea level', 'Ocean waves', 'Air pressure changes across the Pacific', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'Most ENSO events last about:', '9–12 months, sometimes up to 2 years', 'One week', 'Forever', 'Ten years', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'PAGASA declares an ENSO event when:', 'Farmers observe unusual weather', 'One hot day occurs', 'Ocean and atmospheric conditions meet standards for several months', 'News agencies announce it', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'During El Niño, the trade winds:', 'Become stronger', 'Weaken or sometimes reverse direction', 'Stay the same', 'Disappear permanently', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'During El Niño, the warm pool of ocean water:', 'Moves north', 'Sinks', 'Shifts eastward across the Pacific', 'Stays near Asia', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'The Philippines usually experiences fewer typhoons during El Niño because:', 'Storms form farther east and stronger wind shear weakens them', 'Winds completely stop', 'The ocean becomes too cold', 'There is no evaporation', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'During La Niña, more typhoons affect the Philippines because:', 'Less moisture is available', 'Ocean temperatures decrease', 'There is less heat', 'Warm water remains near the Philippines with weaker wind shear', 'D', 'Option D is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'pre_test', 'Which sector is most affected by El Niño?', 'Rain-fed agriculture such as rice and corn farming', 'Manufacturing', 'Factories', 'Urban businesses', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Which combination is commonly associated with El Niño?', 'More rainfall', 'Drought, crop losses, and possible power shortages', 'Cooler temperatures', 'Flooding everywhere', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'La Niña often results in:', 'Water shortage', 'Less wind', 'Heavy rainfall, floods, and landslides', 'Drought', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'ENSO affects countries differently because:', 'It is completely random', 'It affects only the Pacific Ocean', 'It changes global wind and rainfall patterns', 'There is no scientific reason', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Why is monitoring ENSO important?', 'It helps communities prepare for possible disasters', 'It changes the weather', 'It has no practical use', 'It is only for scientists', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Neutral ENSO conditions mean:', 'Always dry weather', 'Climate conditions remain close to average', 'Always wet weather', 'No weather occurs', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Walker Circulation is:', 'A large east-west circulation of air across the Pacific', 'An ocean current', 'A wave pattern', 'A type of wind', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Why does El Niño often cause floods in the Americas but drought in the Philippines?', 'Mountains block rainfall', 'The Philippines is too far away', 'Rainfall shifts eastward with the warm ocean water', 'It happens randomly', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Climate change may affect ENSO by making:', 'Only La Niña occur', 'Extreme ENSO events more frequent or intense', 'ENSO disappear', 'ENSO weaker', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Which sequence correctly describes El Niño?', 'Cooler water → more storms', 'No change occurs', 'Weak trade winds → warm water shifts east → rainfall moves away → drought', 'Stronger winds → more rainfall', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Metro Manila may experience water shortages during El Niño because:', 'Reservoirs receive less rainfall', 'There are no rivers', 'People always waste water', 'Pipe leaks are the only cause', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Which statement correctly describes typhoon tracks?', 'Typhoons always follow the same path', 'El Niño often shifts storms away, while La Niña increases Philippine landfalls', 'ENSO has no effect', 'Storms always hit the Visayas', 'B', 'Option B is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'The 2015–2016 Super El Niño caused:', 'A cooler-than-normal year', 'Better harvests', 'Severe drought, extreme heat, and major crop losses', 'Widespread flooding', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'ENSO affects the Philippine monsoon because:', 'El Niño weakens Habagat, while La Niña strengthens it', 'Monsoons stop completely', 'Only Amihan changes', 'There is no effect', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Why do ENSO impacts differ from one event to another?', 'PAGASA changes its rules', 'Only temperature matters', 'Event strength, timing, location, and climate change all influence the effects', 'It is completely random', 'C', 'Option C is the correct answer.', true),
('b0000000-0000-0000-0000-000000000205', 1, 'post_test', 'Why is it important for students to understand ENSO?', 'It is only needed for examinations', 'It influences food, water, electricity, and public safety', 'It only affects farmers', 'It has no effect on daily life', 'B', 'Option B is the correct answer.', true);
INSERT INTO public.questions (topic_id, question_type_id, quiz_type, question, choice_a, choice_b, choice_c, choice_d, correct_answer, explanation, is_active) VALUES
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', 'Actions that reduce or prevent greenhouse gas emissions are called:', 'Conservation', 'Mitigation', 'Restoration', 'Adaptation', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Mitigation focuses on reducing the causes of climate change. 2. The process of adjusting to the effects of climate change is known as:', 'Prevention', 'Adaptation', 'Reduction', 'Mitigation', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Adaptation helps people and ecosystems cope with climate impacts. 3. Which renewable energy source uses heat from beneath Earth''s surface?', 'Solar', 'Geothermal', 'Wind', 'Hydropower', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Geothermal energy comes from underground heat. 4. Electricity generated from moving water is called:', 'Biomass', 'Hydropower', 'Solar energy', 'Geothermal', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Rivers and dams generate hydropower. 5. Which renewable energy source converts sunlight directly into electricity?', 'Coal', 'Solar energy', 'Wind energy', 'Hydropower', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Solar panels capture energy from sunlight. 6. The largest source of greenhouse gas emissions in the Philippines comes from:', 'Forests', 'Burning coal, oil, and natural gas for electricity and transportation', 'Agriculture', 'Waste disposal', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Fossil fuels are the country''s primary source of emissions. 7. Which is the BEST way for individuals to reduce transportation emissions?', 'Use private vehicles more often', 'Walk, bike, or use public transportation', 'Travel by airplane frequently', 'Buy more plastic products', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Reducing private vehicle use lowers emissions. 8. What do the "3 Rs" stand for?', 'Repair, Replace, Remove', 'Read, Write, Repeat', 'Reduce, Reuse, Recycle', 'Run, Rest, Recover', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ C — Reducing waste comes first, followed by reusing and recycling. 9. Trees help reduce climate change by:', 'Blocking sunlight only', 'Absorbing and storing carbon dioxide (carbon sequestration)', 'Producing oxygen only', 'Cooling the air without storing carbon', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Forests remove CO₂ from the atmosphere and store it. 10. Which is a common impact of climate change in the Philippines?', 'Colder oceans', 'Stronger typhoons, rising sea levels, longer droughts, and hotter days', 'More fish populations', 'Longer harvest seasons', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — These impacts are already being observed. 11. Which of the following is a renewable energy resource found in the Philippines?', 'Coal and oil only', 'Geothermal, hydro, solar, wind, biomass, and ocean energy', 'Coal only', 'Oil only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — The Philippines has abundant renewable energy resources. 12. Renewable energy helps reduce climate change because it:', 'Produces little or no greenhouse gases', 'Is cheaper in every situation', 'Uses more fuel efficiently', 'Makes electricity faster', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ A — Renewable energy emits very little CO₂ during operation. 13. Rising sea levels can cause coastal communities to experience:', 'More beaches', 'Saltwater intrusion, erosion, flooding, and stronger storm surges', 'Cooler seawater', 'No significant effects', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ B — Higher sea levels worsen coastal hazards. 14. Saving electricity helps fight climate change because:', 'It reduces the amount of fuel burned for power generation', 'It only lowers electricity bills', 'It reduces the need for electrical wires', 'It has no effect on emissions', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'pre_test', '✅ A — Lower electricity demand means fewer fossil fuels are burned. 15. Which household action has the greatest impact on reducing carbon emissions?', 'Recycling alone', 'Using energy-efficient appliances, conserving electricity, and installing solar panels', 'Buying less plastic only', 'Driving less once a month', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Reducing home energy use significantly lowers emissions. 16. Composting organic waste helps reduce climate change because it:', 'Makes soil darker', 'Prevents methane production in landfills and reduces the need for synthetic fertilizers', 'Saves water only', 'Produces more oxygen', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Composting lowers methane emissions from waste. 17. Republic Act No. 9513, also known as the Renewable Energy Act, aims to:', 'Ban renewable energy development', 'Promote renewable energy and reduce dependence on imported fossil fuels', 'Increase coal consumption', 'Eliminate hydropower projects', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — The law supports clean and sustainable energy. 18. Climate change affects agriculture by causing:', 'More predictable seasons', 'Unpredictable weather that reduces crop yields and affects food prices', 'Faster crop growth everywhere', 'Fewer agricultural pests', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Changing weather patterns make farming more difficult. 19. Mangrove forests are important because they:', 'Beautify coastlines only', 'Store blue carbon and protect coastal communities from storms', 'Block fishing boats', 'Slow waves only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Mangroves provide both climate mitigation and adaptation benefits. 20. The National Renewable Energy Program (NREP) aims to achieve renewable energy shares of:', '100% immediately', '35% by 2030 and 50% by 2040', '0% renewable energy', 'No renewable energy targets', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — These are the Philippine government''s renewable energy goals. 21. Which statement correctly distinguishes mitigation from adaptation?', 'They mean the same thing', 'Mitigation reduces emissions, while adaptation adjusts to climate impacts', 'Both are only government responsibilities', 'Adaptation prevents greenhouse gas emissions', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — One addresses the cause; the other manages the effects. 22. Geothermal energy is especially important in the Philippines because it:', 'Is available only for export', 'Provides reliable 24-hour electricity using volcanic heat resources', 'Has no installation cost', 'Exists equally in every country', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — The Philippines is rich in geothermal resources due to its volcanic activity. 23. Why is climate adaptation still necessary even if emissions are reduced?', 'Because mitigation does not work', 'Because some climate change is already unavoidable due to past emissions', 'Because laws require it', 'There is no specific reason', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Existing greenhouse gases will continue affecting the climate. 24. Renewable energy benefits the economy by:', 'Increasing dependence on imported fuels', 'Creating jobs, reducing fuel imports, and stabilizing energy prices', 'Slowing economic growth', 'Requiring permanent government subsidies', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Renewable energy supports both economic and environmental goals. 25. Which action contributes to BOTH climate mitigation and adaptation?', 'Turning off lights only', 'Planting native trees, building green roofs, and harvesting rainwater', 'Driving less only', 'Using fewer plastic bags only', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — These actions reduce emissions while helping communities adapt. 26. The Philippines has renewable energy potential that is:', 'Very limited', 'Greater than the country''s current electricity demand', 'Enough only for rural communities', 'Smaller than coal resources', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — The country has abundant renewable energy resources. 27. Climate justice recognizes that:', 'Every country contributes equally to climate change', 'Countries with lower emissions often suffer the greatest climate impacts and deserve support', 'Only developed countries should act', 'Climate change affects everyone equally', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — It focuses on fairness between those causing and experiencing climate impacts. 28. Why do individual daily choices matter in addressing climate change?', 'Individual actions have no effect', 'Many small actions together can reduce emissions and influence businesses and governments', 'They only matter in school activities', 'Governments are the only ones responsible', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Collective individual actions create significant change. 29. One of the biggest challenges to expanding renewable energy in the Philippines is:', 'Lack of sunlight and wind', 'Existing coal contracts, slow permit processes, and limited power grid capacity', 'Renewable energy being too inexpensive', 'Complete public opposition to renewables', 'A', 'Option A is the correct answer.', true),
('b0000000-0000-0000-0000-000000000206', 1, 'post_test', '✅ B — Infrastructure and policy barriers slow renewable energy growth. 30. Why is sustainability important for young people today?', 'It only matters for school examinations', 'Today''s environmental decisions will shape future safety, livelihoods, and quality of life', 'It is only the responsibility of adults', 'It has no personal impact', 'A', 'Option A is the correct answer.', true);
